#include "opensim/services/asset_store.hpp"
#include <iostream>
#include <sstream>
using namespace opensim;using namespace services;
std::string hex(std::string_view s){std::string out;for(unsigned char c:s){out+="0123456789abcdef"[c>>4];out+="0123456789abcdef"[c&15];}return out;}
std::string unhex(const std::string& s){if(s==".")return "";std::string out;for(size_t i=0;i<s.size();i+=2)out+=char(std::stoi(s.substr(i,2),nullptr,16));return out;}
struct Context {std::string trace;int mode,exist;bool stored,deleted;std::string fail;AssetService::Asset a=std::make_shared<framework::AssetBase>(),b=std::make_shared<framework::AssetBase>();Context(){a->id("00000000-0000-0000-0000-000000000001");b->id("00000000-0000-0000-0000-000000000002");a->data=std::make_shared<std::vector<uint8_t>>(std::initializer_list<uint8_t>{1});b->data=std::make_shared<std::vector<uint8_t>>(std::initializer_list<uint8_t>{2});}void event(const std::string& value){trace+=value+";";if(value.starts_with(fail+":")&&!fail.empty())throw std::runtime_error("log");}std::string name(const AssetService::Asset& value){return !value?"N":value==a?"A":value==b?"B":"?";}};
struct Store:AssetStore {Context& c;explicit Store(Context& value):c(value){}AssetService::Asset get(framework::Uuid id)override{c.event("get:"+id.str());if(c.mode==2)throw std::runtime_error("get");return c.mode==1?nullptr:c.mode==3?c.b:c.a;}bool store(AssetService::Asset a)override{c.event("store:"+c.name(a));return c.stored;}std::vector<bool> exists(const std::vector<framework::Uuid>& ids)override{std::string value="exists:";for(auto id:ids)value+=id.str()+",";c.event(value);if(c.exist==3)throw std::runtime_error("exists");return c.exist==0?std::vector<bool>{}:std::vector<bool>{c.exist==2};}std::vector<std::shared_ptr<framework::AssetMetadata>> metadata_set(int32_t,int32_t)override{return {};}bool erase(const std::string& id)override{c.event("delete:"+id);return c.deleted;}};
int main(){std::string line;while(std::getline(std::cin,line)){std::istringstream in(line);Context c;std::string id,ops;int stored,deleted;in>>c.mode>>c.exist>>stored>>deleted>>c.fail>>id>>ops;c.stored=stored!=0;c.deleted=deleted!=0;if(c.fail=="-")c.fail="";id=unhex(id);auto data=std::make_shared<Store>(c);StoredAssetService service(data,{[&](const auto& message){c.event("warn:"+message);},[&](const auto& message,const auto&){c.event("error:"+message);}});std::string result;
 for(char op:ops){std::string value="-";try{switch(op){case 'G':value=c.name(service.get_asset(id));break;case 'C':value=c.name(service.get_cached(id));break;case 'M':{auto m=service.get_metadata(id);value=!m?"N":m==c.a->metadata()?"A":m==c.b->metadata()?"B":"?";break;}case 'D':{auto bytes=service.get_data(id);value=!bytes?"N":bytes==c.a->data?"A":bytes==c.b->data?"B":"?";break;}case 'A':case 'R':case 'Q':{AssetService::Retrieved cb;if(op!='Q')cb=[&](const auto& key,std::any sender,auto asset){c.event("callback:"+key+":"+std::any_cast<std::string>(sender)+":"+c.name(asset));if(op=='R')throw std::runtime_error("callback");};value=service.get_async(id,std::string("sender"),cb)?"1":"0";break;}case 'F':service.get(id,"foreign",true,[&](auto asset){c.event("simple:"+c.name(asset));});break;case 'S':case 's':value=service.store(op=='s'?nullptr:c.a).value_or("N");break;case 'U':value=service.update_content(id,{})?"1":"0";break;case 'X':value=service.erase(id)?"1":"0";break;case 'E':case 'e':{auto values=service.assets_exist(op=='e'?std::vector<std::string>{}:std::vector<std::string>{id,c.a->id()});value="";for(bool b:values)value+=b?'1':'0';break;}case 'T':c.a->metadata({});break;}}catch(...){value="EX";}result+=std::string(1,op)+":"+hex(value)+";";}std::cout<<result<<'|'<<hex(c.trace)<<'\n';}}
